using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Web.Script.Serialization;
namespace PZ3D {static class SaveProfilesNoopTests {
 static int checks;static readonly string[] Components={"ZombieBuddy","Viewpoint","PZVoxelStudioViewpoint","ProjectViewpointShelves","ViewpointTrueWeathers","ProjectViewpointNearVegetation","LaoYuTranslationJava"};
 static void Check(bool value,string reason){if(!value)throw new Exception("FAIL "+reason);checks++;Console.WriteLine("PASS "+reason);}
 static Dictionary<string,object> D(object value){var json=new JavaScriptSerializer();return json.Deserialize<Dictionary<string,object>>(json.Serialize(value));}
 static string[] Enabled(Dictionary<string,object> row){return ((IEnumerable)row["enabled"]).Cast<object>().Select(item=>(string)item).ToArray();}
 static string Text(params string[] ids){return "VERSION = 1,\r\nmods\r\n{\r\n"+string.Concat(ids.Select(id=>"  mod = "+id+",\r\n"))+"}\r\nmaps\r\n{\r\n  map = Muldraugh, KY,\r\n}\r\ncustom\r\n{\r\n  keep = exact,\r\n}\r\n";}
 static void Put(string file,string text){Directory.CreateDirectory(Path.GetDirectoryName(file));File.WriteAllText(file,text,new UTF8Encoding(false));}
 sealed class Fixture {internal readonly string Root,Game,User,Data,Save;internal readonly Engine Engine;internal Fixture(string parent,string kind){Root=Path.Combine(parent,kind);Game=Path.Combine(Root,"steamapps","common","ProjectZomboid");User=Path.Combine(Root,"user");Data=Path.Combine(Root,"data");Save=Path.Combine(User,"Saves","Sandbox","Original","mods.txt");Put(Path.Combine(Game,"ProjectZomboid64.exe"),"synthetic game never executed");Put(Path.Combine(Game,"ProjectZomboid64.json"),"{\"mainClass\":\"zombie/gameStates/MainScreenState\",\"classpath\":[\".\",\"projectzomboid.jar\"],\"vmArgs\":[]}");Put(Path.Combine(Game,"version.txt"),"42.21.0");Put(Path.Combine(Game,"game-version.txt"),"42.21.0");foreach(string id in Components.Concat(new[]{"A","B"}))Put(Path.Combine(User,"mods",id,"42","mod.info"),"id="+id+"\n");Put(Path.Combine(User,"mods","default.txt"),Text(Components.Concat(new[]{"A"}).ToArray()));Put(Save,Text("A","B"));File.WriteAllText(Save,Text("A","B"),new UTF8Encoding(true));Engine=new Engine(Game,User,Data,true,null,name=>new System.Diagnostics.Process[0]);if(kind=="managed")Engine.ManagedVersion=true;}}
 static void Noop(Engine engine,string file,string label){byte[] before=File.ReadAllBytes(file);DateTime time=new DateTime(2020,1,2,3,4,5,DateTimeKind.Utc);File.SetLastWriteTimeUtc(file,time);var read=D(SaveProfiles.Read(engine,"Sandbox/Original"));Check(Enabled(read).SequenceEqual(new[]{"A","B"}),label+" reads only the original save mods despite seven managed defaults");var saved=D(SaveProfiles.Save(engine,"Sandbox/Original",(string)read["stamp"],Enabled(read),false));Check(Enabled(saved).SequenceEqual(new[]{"A","B"}),label+" unchanged Save adds none of the seven managed default components");Check(File.ReadAllBytes(file).SequenceEqual(before)&&File.GetLastWriteTimeUtc(file)==time,label+" unchanged Save preserves BOM, CRLF, maps, unknown blocks, exact bytes and modification time");using(var locked=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read)){saved=D(SaveProfiles.Save(engine,"Sandbox/Original",(string)saved["stamp"],Enabled(saved),true));}Check(File.ReadAllBytes(file).SequenceEqual(before)&&File.GetLastWriteTimeUtc(file)==time,label+" unchanged Save needs no write/delete access to the existing file");SaveProfiles.ValidateForLaunch(engine,"Sandbox/Original");Check(true,label+" next normal save validation still succeeds");}
 static void SourceAndManaged(string root){foreach(string kind in new[]{"source","managed"}){var f=new Fixture(root,kind);Noop(f.Engine,f.Save,kind);var old=D(SaveProfiles.Read(f.Engine,"Sandbox/Original"));File.AppendAllText(f.Engine.Mods,"\r\n");bool stale=false;try{SaveProfiles.Save(f.Engine,"Sandbox/Original",(string)old["stamp"],Enabled(old),true);}catch(Exception error){stale=error.Message.Contains("修改");}Check(stale,kind+" stale stamp is refused before the unchanged-list shortcut");var read=D(SaveProfiles.Read(f.Engine,"Sandbox/Original"));SaveProfiles.Save(f.Engine,"Sandbox/Original",(string)read["stamp"],new[]{"A"},true);Check(SaveProfiles.DefaultMods(File.ReadAllBytes(f.Save)).SequenceEqual(Components.Concat(new[]{"A"})),kind+" genuine edits retain existing managed-component merging");}}
 static void InheritedAndMissingCatalog(string root){var f=new Fixture(root,"inherited");File.Delete(f.Save);var inherited=D(SaveProfiles.Read(f.Engine,"Sandbox/Original"));bool refused=false;try{SaveProfiles.Save(f.Engine,"Sandbox/Original",(string)inherited["stamp"],Enabled(inherited),false);}catch{refused=true;}Check(refused&&!File.Exists(f.Save),"unchanged inherited selection still requires confirmation before creating mods.txt");SaveProfiles.Save(f.Engine,"Sandbox/Original",(string)inherited["stamp"],Enabled(inherited),true);Check(File.Exists(f.Save),"confirmed inherited selection still creates its first independent save configuration");Put(f.Save,Text("UnresolvedButUnchanged"));var row=D(SaveProfiles.Read(f.Engine,"Sandbox/Original"));byte[] before=File.ReadAllBytes(f.Save);SaveProfiles.Save(f.Engine,"Sandbox/Original",(string)row["stamp"],Enabled(row),false);Check(File.ReadAllBytes(f.Save).SequenceEqual(before),"unchanged Save does not require a full catalog/dependency scan for an unresolved existing mod");bool invalid=false;try{SaveProfiles.Save(f.Engine,"Sandbox/Original",(string)row["stamp"],new[]{"UnresolvedButUnchanged","UnresolvedButUnchanged"},true);}catch{invalid=true;}Check(invalid,"duplicate requested IDs still fail before any no-op handling");}
 static void SourceControllerAndFrozen(string root){var f=new Fixture(root,"controller-frozen");var store=new SaveEnvironments(f.Engine);var plan=store.Preview("Sandbox/Original");Check(plan.ready,"independent snapshot fixture resolves ordinary and managed default sources");var record=store.Create("Sandbox/Original",Path.Combine(f.Root,"snapshot"),"no-op regression",plan.stamp,CancellationToken.None,null,row=>SaveEnvironmentRuntime.Prepare(f.Engine,row));var frozen=SaveEnvironmentRuntime.ForSave(f.Engine,"Sandbox/Original");SaveEnvironmentRuntime.Validate(frozen,"Sandbox/Original");byte[] original=File.ReadAllBytes(f.Save);DateTime time=new DateTime(2020,2,3,4,5,6,DateTimeKind.Utc);File.SetLastWriteTimeUtc(f.Save,time);using(var controller=new ModernController(f.Game,f.User,f.Data,true)){var read=D(controller.Execute("saveGet",new Dictionary<string,object>{{"id","Sandbox/Original"}}));var result=D(controller.Execute("saveSave",new Dictionary<string,object>{{"id","Sandbox/Original"},{"stamp",read["stamp"]},{"mods",Enabled(read)},{"confirmed",false}}));Check(Enabled(result).SequenceEqual(new[]{"A","B"})&&File.ReadAllBytes(f.Save).SequenceEqual(original)&&File.GetLastWriteTimeUtc(f.Save)==time,"real source-controller saveGet/saveSave keeps the bound snapshot save bytes and time unchanged");}SaveEnvironmentRuntime.Validate(SaveEnvironmentRuntime.ForSave(f.Engine,"Sandbox/Original"),"Sandbox/Original");Check(true,"source-controller no-op preserves the next bound snapshot validation");Noop(frozen,f.Save,"ForSave frozen engine");SaveEnvironmentRuntime.Validate(frozen,"Sandbox/Original");Check(record.SaveModsBytes.SequenceEqual(File.ReadAllBytes(f.Save)),"direct frozen no-op retains original captured save bytes and passes runtime validation");}
 public static int Main(){LauncherRuntime.Initialize();string root=Path.Combine(LauncherTestPaths.Root,"save-noop-"+Guid.NewGuid().ToString("N"));try{SourceAndManaged(root);InheritedAndMissingCatalog(root);SourceControllerAndFrozen(root);Console.WriteLine("SaveProfiles NOOP PASS: "+checks+" assertions");SaveProfilesTests.Run();return 0;}catch(Exception error){Console.WriteLine(error);return 1;}finally{string full=Path.GetFullPath(root),parent=Path.GetFullPath(LauncherTestPaths.Root)+Path.DirectorySeparatorChar;if(!full.StartsWith(parent,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(full).StartsWith("save-noop-",StringComparison.Ordinal))throw new IOException("Unsafe no-op fixture cleanup");if(Directory.Exists(full))Directory.Delete(full,true);}}
}}
